def seed_universe_companies(store: Optional[ResearchDataStore] = None) -> int:
    """Discovers and seeds full ₹100 Cr – ₹1 Lakh Cr market cap universe into `companies` table.

    Preserves existing 30 mega-cap companies as a subset.
    Returns the total count of seeded companies in the database.
    """
    data_store = store or ResearchDataStore()
    seeded = 0
    for comp in EXPANDED_UNIVERSE_MASTERS:
        try:
            data_store.upsert_company(comp)
            seeded += 1
        except Exception as exc:
            logger.warning(f"Failed to upsert company {comp['symbol']}: {exc}")
    
    with data_store._connect() as conn:
        total_count = conn.execute("SELECT COUNT(*) FROM companies").fetchone()[0]
    
    logger.info(f"Universe discovery seeding complete: {seeded} symbols processed, {total_count} total companies in DB.")
    return total_count


if __name__ == "__main__":
    count = seed_universe_companies()
    print(f"Seeded universe companies count: {count}")
